#include <stdio.h>
#include <string.h>

int longestSubstring(const char* s, int k) {
    int n = (int)strlen(s);
    if (k <= 1) return n;

    int best = 0;
    for (int target = 1; target <= 26; ++target) {
        int cnt[26] = {0};
        int left = 0, right = 0, unique = 0, atLeastK = 0;

        while (right < n) {
            int idx = s[right] - 'a';
            if (cnt[idx] == 0) ++unique;
            ++cnt[idx];
            if (cnt[idx] == k) ++atLeastK;
            ++right;

            while (unique > target) {
                int li = s[left] - 'a';
                if (cnt[li] == k) --atLeastK;
                --cnt[li];
                if (cnt[li] == 0) --unique;
                ++left;
            }

            if (unique == target && atLeastK == target) {
                int len = right - left;
                if (len > best) best = len;
            }
        }
    }
    return best;
}

