    public int longestSubstring(String s, int k) {
        int n = s.length();
        if (k <= 1) return n;

        int best = 0;
        for (int target = 1; target <= 26; target++) {
            int[] count = new int[26];
            int left = 0, right = 0, unique = 0, atLeastK = 0;

            while (right < n) {
                int idx = s.charAt(right) - 'a';
                if (count[idx] == 0) unique++;
                count[idx]++;
                if (count[idx] == k) atLeastK++;
                right++;

                while (unique > target) {
                    int li = s.charAt(left) - 'a';
                    if (count[li] == k) atLeastK--;
                    count[li]--;
                    if (count[li] == 0) unique--;
                    left++;
                }

                if (unique == target && atLeastK == target) {
                    best = Math.max(best, right - left);
                }
            }
        }
        return best;
    }
}

